<script setup lang="ts">
const {form,options,selectedId,previewHref,loading,saving,loaded,error,notice,isDirty,load,save,discard,selectObject,addRow,removeRow,moveRow,addColumn,removeColumn,moveColumn}=useAdminObjectEquipment()
</script>
<template>
 <div class="mx-auto w-full max-w-7xl space-y-6 px-5 py-8 tablet:px-8">
  <div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-semibold">Обслуживаемое оборудование</h1><p class="mt-2 text-sm text-slate-500">Заголовок, таблица и описание сохраняются отдельно для выбранного объекта.</p></div><div class="flex gap-2"><UButton label="Отменить" variant="outline" color="neutral" :disabled="loading||saving||!isDirty" @click="discard"/><UButton label="Сохранить" :loading="saving" :disabled="loading||!isDirty" @click="save"/></div></div>
