   <UCard><template #header><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="font-semibold">Таблица</h2><div class="flex gap-2"><UButton label="Добавить столбец" icon="i-lucide-columns-3" variant="outline" :disabled="form.columns.length>=8" @click="addColumn"/><UButton label="Добавить строку" icon="i-lucide-plus" variant="outline" :disabled="form.rows.length>=100" @click="addRow"/></div></div></template>
