    <div class="overflow-x-auto"><table class="w-full table-fixed border-collapse" :style="{minWidth:`${form.columns.length*220+130}px`}"><caption class="sr-only">Редактирование таблицы оборудования</caption><thead><tr><th v-for="(column,index) in form.columns" :key="column.id" class="border border-slate-200 p-3 align-top"><UInput v-model="column.title" :aria-label="`Название столбца ${index+1}`" maxlength="120" class="w-full"/><div class="mt-2 flex justify-center"><UButton icon="i-lucide-arrow-left" :aria-label="`Переместить столбец ${index+1} влево`" variant="ghost" color="neutral" :disabled="index===0" @click="moveColumn(index,-1)"/><UButton icon="i-lucide-arrow-right" :aria-label="`Переместить столбец ${index+1} вправо`" variant="ghost" color="neutral" :disabled="index===form.columns.length-1" @click="moveColumn(index,1)"/><UButton icon="i-lucide-trash-2" :aria-label="`Удалить столбец ${index+1}`" variant="ghost" color="error" :disabled="form.columns.length===1" @click="removeColumn(index)"/></div></th><th class="w-32 border border-slate-200 p-3 text-sm">Порядок строк</th></tr></thead><tbody><tr v-for="(row,index) in form.rows" :key="row.id"><td v-for="(column,columnIndex) in form.columns" :key="column.id" class="border border-slate-200 p-3 align-top"><UTextarea v-model="row.cells[columnIndex]" :aria-label="`Строка ${index+1}, ${column.title||`столбец ${columnIndex+1}`}`" :rows="2" maxlength="1000" class="w-full"/></td><td class="border border-slate-200 p-2"><div class="flex justify-center"><UButton icon="i-lucide-arrow-up" :aria-label="`Поднять строку ${index+1}`" variant="ghost" color="neutral" :disabled="index===0" @click="moveRow(index,-1)"/><UButton icon="i-lucide-arrow-down" :aria-label="`Опустить строку ${index+1}`" variant="ghost" color="neutral" :disabled="index===form.rows.length-1" @click="moveRow(index,1)"/><UButton icon="i-lucide-trash-2" :aria-label="`Удалить строку ${index+1}`" variant="ghost" color="error" @click="removeRow(index)"/></div></td></tr></tbody></table></div>
